package com.otectus.immersivejewelry.minigame.setting;

import com.otectus.immersivejewelry.minigame.StepClock;
import com.otectus.immersivejewelry.recipe.SettingStyle;
import net.minecraft.network.FriendlyByteBuf;
import net.minecraft.util.Mth;

import java.util.Random;

/**
 * Parameters of a setting (or removal) session, generated by the server and sent whole to the client.
 *
 * @param angles     point angles around the stones (radians), grouped per stone
 * @param stoneOf    which stone each point holds
 * @param order      points in the order they must be worked (balanced: opposite points in turn)
 * @param opposite   the point across the stone from each point (-1 for none)
 * @param base       pressure target of a point whose opposite is not yet set
 * @param jitter     per-point offset of that target
 * @param window     half-width of each pressure window
 * @param fillRate   pressure per second while squeezing
 * @param chipAbove  pressure above which a brittle stone chips (above 1 = never)
 * @param removal    lifting prongs to remove the stones rather than setting them
 * @param maxSteps   session length in steps
 */
public record SettingParams(SettingStyle style, int stones, float[] angles, int[] stoneOf, int[] order, int[] opposite, float base,
                            float[] jitter, float window, float fillRate, float chipAbove, boolean removal, int maxSteps) {

    public record Inputs(SettingStyle style, int stones, int pointsPerStone, float tightness, float precision, float stoneSize,
                         float brittleness, float configDifficulty, boolean largerTargets, boolean slower, boolean removal,
                         int secondsPerPoint) {}

    public int points() {
        return angles.length;
    }

    public static SettingParams create(Inputs in, long seed) {
        Random random = new Random(seed);
        int per = Mth.clamp(in.pointsPerStone(), 2, 12);
        int stones = Mth.clamp(in.stones(), 1, 8);
        int n = per * stones;
        float[] angles = new float[n];
        int[] stoneOf = new int[n];
        int[] order = new int[n];
        int[] opposite = new int[n];
        float[] jitter = new float[n];
        int o = 0;
        for (int s = 0; s < stones; s++) {
            float rotation = in.style() == SettingStyle.BEZEL ? 0F : Mth.PI / per;
            for (int i = 0; i < per; i++) {
                int idx = s * per + i;
                angles[idx] = rotation + i * Mth.TWO_PI / per;
                stoneOf[idx] = s;
                opposite[idx] = per % 2 == 0 ? s * per + (i + per / 2) % per : -1;
                jitter[idx] = (random.nextFloat() - 0.5F) * 0.14F;
            }
            // 1 -> 3 -> 2 -> 4 for four prongs; generally each point then its opposite.
            if (per % 2 == 0) {
                for (int i = 0; i < per / 2; i++) {
                    order[o++] = s * per + i;
                    order[o++] = s * per + i + per / 2;
                }
            } else {
                for (int i = 0; i < per; i++) order[o++] = s * per + (i * 2) % per;
            }
        }
        float difficulty = Mth.clamp(in.tightness() * in.configDifficulty(), 0.25F, 4F);
        float small = 0.9F + 0.1F * Mth.clamp(in.stoneSize(), 0.3F, 1.5F);
        float window = Mth.clamp(0.1F * in.precision() * small * (in.largerTargets() ? 1.4F : 1F)
                / (float) Math.sqrt(difficulty) * (in.style() == SettingStyle.BEZEL ? 1.15F : 1F) * (in.removal() ? 1.3F : 1F), 0.035F, 0.25F);
        float fill = 0.5F * (in.slower() ? 0.7F : 1F) * (in.style() == SettingStyle.BEZEL ? 0.85F : 1F);
        float base = in.removal() ? 0.32F : 0.62F;
        float chipAbove = in.brittleness() > 0.3F ? 1.02F - 0.12F * in.brittleness() : 2F;
        int maxSteps = n * Math.max(2, in.secondsPerPoint()) * 1000 / StepClock.STEP_MS;
        return new SettingParams(in.style(), stones, angles, stoneOf, order, opposite, base, jitter, window, fill, chipAbove,
                in.removal(), maxSteps);
    }

    public void write(FriendlyByteBuf buf) {
        buf.writeEnum(style);
        buf.writeVarInt(stones);
        buf.writeVarInt(angles.length);
        for (int i = 0; i < angles.length; i++) {
            buf.writeFloat(angles[i]);
            buf.writeVarInt(stoneOf[i]);
            buf.writeVarInt(order[i]);
            buf.writeVarInt(opposite[i] + 1);
            buf.writeFloat(jitter[i]);
        }
        buf.writeFloat(base);
        buf.writeFloat(window);
        buf.writeFloat(fillRate);
        buf.writeFloat(chipAbove);
        buf.writeBoolean(removal);
        buf.writeVarInt(maxSteps);
    }

    public static SettingParams read(FriendlyByteBuf buf) {
        SettingStyle style = buf.readEnum(SettingStyle.class);
        int stones = Mth.clamp(buf.readVarInt(), 1, 8);
        int n = Mth.clamp(buf.readVarInt(), 2, 96);
        float[] angles = new float[n];
        int[] stoneOf = new int[n];
        int[] order = new int[n];
        int[] opposite = new int[n];
        float[] jitter = new float[n];
        for (int i = 0; i < n; i++) {
            angles[i] = buf.readFloat();
            stoneOf[i] = Mth.clamp(buf.readVarInt(), 0, stones - 1);
            order[i] = Mth.clamp(buf.readVarInt(), 0, n - 1);
            opposite[i] = Mth.clamp(buf.readVarInt() - 1, -1, n - 1);
            jitter[i] = buf.readFloat();
        }
        return new SettingParams(style, stones, angles, stoneOf, order, opposite, buf.readFloat(), jitter, buf.readFloat(),
                buf.readFloat(), buf.readFloat(), buf.readBoolean(), buf.readVarInt());
    }
}
